    testOfflineListSync,
    customSourcesFlat,
    npmTestGlobCoverage,
    pipelineSiteAgnostic,
    regenArtifactsMergeOurs,
  ],
  skills: ['snapshot-approval', 'merge-and-ci', 'testing-guide'],
};

